from fractions import Fraction

MODES = ['RNE', 'RNA', 'RTZ', 'RUP', 'RDN']

def bits_for(ebits, fbits, s, e, f):
    return format((s << (ebits + fbits)) | (e << fbits) | f, 'x')

def run(req, label):
    return check(req, label)

def test_normal_tie(ebits, fbits, trials, seed):
    rnd = random.Random(seed)
    F = 1 << fbits
    bias = (1 << (ebits - 1)) - 1
    Eall = (1 << ebits) - 1
    emin = 1 - bias; emax = Eall - 1 - bias
    shift = ebits + fbits
    for i in range(trials):
        t = rnd.randrange(F, 2 * F)
        s = rnd.randrange(emin + 1, emax - fbits + 1)
        A = bits_for(ebits, fbits, 0, fbits + bias, t - F)          # t * 2^0
        B = bits_for(ebits, fbits, 0, s + bias, 0)                  # 2^s
        C = bits_for(ebits, fbits, 0, (s - 1) + bias, 0)            # 2^(s-1)
        D = bits_for(ebits, fbits, 0, bias, 0)                      # 1.0
        for neg in (0, 1):
            if neg:
                A2 = bits_for(ebits, fbits, 1, fbits + bias, t - F)
            else:
                A2 = A
            for mode in MODES:
                req = {'ebits': ebits, 'fbits': fbits, 'mode': mode,
